# apply_tracks_fix_and_run.py — updates tracks.py + normalizer, then
# re-classifies existing races.parquet + entries.parquet track_type using
# the fixed lookup.
import base64, pathlib, subprocess, sys

FILES = {
    'src/features/tracks.py': '',
    'src/scrape/nascar_com.py': '',
}


def main():
    for target, b64 in FILES.items():
        p = pathlib.Path(target)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(base64.b64decode(b64))
        print(f"wrote {target}")

    import pandas as pd
    from src.scrape.nascar_com import track_type_for

    print("\nRe-classifying existing races.parquet + entries.parquet ...")
    races = pd.read_parquet("data/processed/races.parquet")
    entries = pd.read_parquet("data/processed/entries.parquet")

    old = races["track_type"].copy()
    races["track_type"] = races["track_name"].apply(track_type_for)
    changed = (old != races["track_type"]).sum()
    print(f"races.parquet: {changed} rows re-classified")

    if changed > 0:
        changes = races[old != races["track_type"]][["race_name", "track_name", "date"]]
        changes["from"] = old[old != races["track_type"]].values
        changes["to"] = races.loc[old != races["track_type"], "track_type"].values
        print("\nWhich races changed track_type:")
        print(changes.to_string(index=False))

    # Update entries.parquet track_type from races via join.
    tt_map = dict(zip(races["race_id_short"], races["track_type"]))
    old_e = entries["track_type"].copy()
    entries["track_type"] = entries["race_id_short"].map(tt_map).fillna(entries["track_type"])
    changed_e = (old_e != entries["track_type"]).sum()
    print(f"\nentries.parquet: {changed_e} rows re-classified")

    races.to_parquet("data/processed/races.parquet", index=False)
    entries.to_parquet("data/processed/entries.parquet", index=False)
    print("\nDone. Rerun backtest_oddslogic_v4.py to see the effect on Wilkesboro.")

if __name__ == "__main__":
    main()
